// Generated by scripts/generate-table.mjs from src/table-source.json. Do not edit.

export const TIERS = Object.freeze([
  Object.freeze({ id: "gold", floor: 0 }),
  Object.freeze({ id: "silver", floor: 320 }),
  Object.freeze({ id: "bronze", floor: 160 }),
  Object.freeze({ id: "plain", floor: 0 }),
]);

/** The first tier whose floor the score reaches. */
export function tierOf(score) {
  for (const tier of TIERS) if (score >= tier.floor) return tier.id;
  return 'plain';
}
